/* Legal Staff admin: Email Marketing module. Loaded by admin.html; talks only to the email-marketing function (no keys in the browser). */
(window.LSAdminExtensions = window.LSAdminExtensions || []).push(function (A) {
  const { sb, esc, dt, day, toast, modal, VIEWS, TABS } = A;
  

  const SUBS = [['overview', 'Overview'], ['contacts', 'Contact Database'], ['sheets', 'Google Sheets Integration'], ['new', 'New Email Campaigns'], ['reminders', 'Reminder Campaigns'], ['templates', 'Email Templates'],
    ['queue', 'Sending Queue'], ['history', 'Email History'], ['unsub', 'Unsubscribed Contacts'], ['analytics', 'Campaign Analytics'], ['settings', 'Automation Settings']];
  // the main sidebar shows these as grouped sub-options under Email Marketing
  const SUB_GROUPS = [[null, ['overview']], ['Audience', ['contacts', 'sheets', 'unsub']], ['Campaigns', ['new', 'reminders', 'templates']], ['Delivery', ['queue', 'history', 'analytics']], ['Setup', ['settings']]];
  TABS.push(['email', 'Email Marketing', SUB_GROUPS.map(([g, keys]) => [g, keys.map(k => SUBS.find(x => x[0] === k))])]);
  const n = v => Number(v || 0).toLocaleString('en-IN');
  const cs = {};   // remembered filters / page per screen
  async function api(action, body = {}) {
    const r = await sb.functions.invoke('email-marketing', { body: Object.assign({ action }, body) });
    if (r.error) { let m = r.error.message; try { const j = await r.error.context.json(); if (j && j.error) m = j.error; } catch (e) {} throw new Error(m); }
    return r.data;
  }
  const chipOf = (v, map) => { const [t, c] = map[v] || [v, 'c-mut']; return `<span class="chip ${c}">${esc(t)}</span>`; };
  const CONSENT = { UNKNOWN: ['Unknown', 'c-mut'], GRANTED: ['Granted', 'c-good'], WITHDRAWN: ['Withdrawn', 'c-bad'] };
  const FIRST = { BLOCKED: ['Blocked', 'c-mut'], ELIGIBLE: ['Eligible', 'c-info'], QUEUED: ['Queued', 'c-warn'], SENT: ['Sent', 'c-good'], FAILED: ['Failed', 'c-bad'] };
  const QSTAT = { queued: ['Queued', 'c-warn'], sending: ['Sending', 'c-info'], sent: ['Sent', 'c-good'], skipped: ['Skipped', 'c-mut'], failed: ['Failed', 'c-bad'], accepted: ['Accepted', 'c-good'] };
  const REG = { NONE: ['—', 'c-mut'], STARTED: ['Started', 'c-warn'], COMPLETED: ['Registered', 'c-good'] };
  const PAY = { NONE: ['—', 'c-mut'], PAID: ['Paid ₹49', 'c-good'] };
  const reminderText = c => c.unsubscribe_status === 'UNSUBSCRIBED' ? 'Stopped (unsubscribed)' : c.hard_bounced || c.spam_complaint ? 'Stopped' : c.first_email_status !== 'SENT' ? '—' : c.reminder_count >= 2 || !c.reminder_due_date ? `${c.reminder_count} sent · done` : `${c.reminder_count} sent · due ${day(c.reminder_due_date)}`;
  const kpi = (l, v, s, cls) => `<div class="card kpi"><div class="k">${l}</div><div class="v ${cls || ''}">${v}</div>${s ? `<div class="s">${s}</div>` : ''}</div>`;
  const pager = (page, total, size) => `<div class="row between" style="margin-top:12px"><div class="muted small">${total ? `${n(page * size + 1)}–${n(Math.min(total, page * size + size))} of ${n(total)}` : 'No results'}</div><div class="row"><button class="btn sm" data-pg="-1" ${page <= 0 ? 'disabled' : ''}>Previous</button><button class="btn sm" data-pg="1" ${(page + 1) * size >= total ? 'disabled' : ''}>Next</button></div></div>`;
  const tbl = (head, rows, empty) => `<div class="tscroll"><table><thead><tr>${head.map(h => `<th class="${h[1] || ''}">${h[0]}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.join('') : `<tr><td colspan="${head.length}" class="empty">${empty || 'Nothing here yet.'}</td></tr>`}</tbody></table></div>`;
  const download = (name, mime, content) => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([content], { type: mime + ';charset=utf-8' })); a.download = name; document.body.appendChild(a); a.click(); a.remove(); };
  const busy = async (btn, label, fn) => { const old = btn.textContent; btn.disabled = true; btn.textContent = label; try { return await fn(); } catch (e) { toast(e.message); } finally { btn.disabled = false; btn.textContent = old; } };

  // ---------- charts (inline SVG, no library) ----------
  function barChart(series, keys, colors, h = 190) {
    const W = 720, pad = 28, max = Math.max(1, ...series.map(d => keys.reduce((s, k) => s + (d[k] || 0), 0))), bw = (W - pad * 2) / series.length;
    const bars = series.map((d, i) => { let y = h - 24; return keys.map((k, j) => { const v = d[k] || 0, hh = v / max * (h - 44); y -= hh; return v ? `<rect x="${pad + i * bw + 3}" y="${y}" width="${Math.max(2, bw - 6)}" height="${hh}" rx="2" fill="${colors[j]}"><title>${esc(d.date)} · ${k}: ${v}</title></rect>` : ''; }).join(''); }).join('');
    const labels = series.map((d, i) => (i % Math.ceil(series.length / 8) === 0 ? `<text x="${pad + i * bw + bw / 2}" y="${h - 6}" font-size="10" text-anchor="middle" fill="#6B6B6B">${esc(d.date.slice(5))}</text>` : '')).join('');
    return `<svg viewBox="0 0 ${W} ${h}" role="img" aria-label="Daily activity"><line x1="${pad}" x2="${W - pad}" y1="${h - 24}" y2="${h - 24}" stroke="#E5E5E5"/><text x="${pad}" y="12" font-size="10" fill="#6B6B6B">max ${max}</text>${bars}${labels}</svg>`;
  }
  const legend = (items) => `<div class="legend">${items.map(([c, l]) => `<span><i style="background:${c}"></i>${l}</span>`).join('')}</div>`;
  const COL = { a: '#0A0A0A', b: '#2a78d6', c: '#eb6834', d: '#137333' };

  // ---------- layout: sidebar with the eleven submenus ----------
  function shell(p, sub, render) {
    p.innerHTML = `<div class="em"><section class="em-main" id="em-main"><div class="skel-block"><i></i><i></i><i></i></div></section></div>`;
    const m = p.querySelector('#em-main');
    const run = () => render(m).catch(e => { m.innerHTML = `<div class="card err">${esc(e.message)} <button class="btn sm" id="retry" style="margin-left:10px">Try again</button></div>`; m.querySelector('#retry').onclick = () => { m.innerHTML = '<div class="skel-block"><i></i><i></i><i></i></div>'; run(); }; });
    run();
  }
  const style = document.createElement('style');
  style.textContent = `.em{display:block}
  .em-main{min-width:0}.em-main .card{box-shadow:none}.em-main h1{margin-bottom:2px}.em-main td{padding:11px 9px}.em-main td.strong{white-space:nowrap}
  .vars{display:block;font-weight:400;line-height:2}.vars code{background:#F0F0EE;border-radius:5px;padding:1px 6px;font-size:12px;margin-right:2px;color:#363636}
  .banner{border:1px solid;border-radius:10px;padding:12px 14px;font-size:13.5px;margin-bottom:14px}.banner.warn{background:var(--warnbg);border-color:#F6D6A8;color:#7A3A06}.banner.ok{background:var(--goodbg);border-color:#BFE3CB;color:#0E5A28}.banner.bad{background:var(--badbg);border-color:#F3C3BE;color:var(--bad)}
  .banner ul{margin:6px 0 0 18px;padding:0}.em .k3{grid-template-columns:repeat(3,minmax(0,1fr))}.em .k6{grid-template-columns:repeat(6,minmax(0,1fr))}
  .frame{border:1px solid var(--line);border-radius:10px;background:#fff;width:100%;height:520px}.tpl-item{padding:12px 14px;border-bottom:1px solid #EFEFEE;cursor:pointer}.tpl-item.on{background:var(--soft)}
  .switch{display:flex;gap:8px;align-items:center}.switch input{width:auto;height:auto}.mono{font-family:ui-monospace,Menlo,monospace;font-size:12.5px}
  @media (max-width:900px){.em .k3,.em .k6{grid-template-columns:repeat(2,minmax(0,1fr))}}`;
  document.head.appendChild(style);

  VIEWS.email = async (p, sub) => {
    sub = SUBS.some(s => s[0] === (sub || '').split(':')[0]) ? sub : 'overview';
    const key = sub.split(':')[0];
    shell(p, key, m => SCREENS[key](m, sub.split(':')[1]));
  };

  const SCREENS = {};

  // ---------- 1. overview ----------
  SCREENS.overview = async m => {
    const o = await api('overview'), c = o.cards, s = o.settings, mode = s.kill_switch ? 'bad' : o.blockers.length ? 'warn' : 'ok';
    m.innerHTML = `<h1>Overview</h1><p class="sub">Automated outreach to advocates · all times India time</p>
      <div class="banner ${mode}"><b>${s.kill_switch ? 'Emergency stop is ON: nothing is being sent.' : o.blockers.length ? 'Sending is disabled.' : 'Production sending is active.'}</b>
        ${o.blockers.length && !s.kill_switch ? `<ul>${o.blockers.map(b => `<li>${esc(b)}</li>`).join('')}</ul>` : ''}
        <div class="row" style="margin-top:8px"><button class="btn sm ${s.kill_switch ? '' : 'danger'}" id="kill">${s.kill_switch ? 'Resume (turn emergency stop off)' : 'Emergency stop: halt all sending now'}</button><a class="btn sm" href="#email/settings" style="text-decoration:none;color:var(--ink);display:inline-flex;align-items:center">Automation settings</a></div></div>
      <div class="grid k4">
        ${kpi('Contacts imported', n(c.total))}${kpi('Eligible marketing contacts', n(c.eligible), 'Documented permission, verified, not suppressed')}${kpi('Awaiting permission', n(c.awaiting), 'Blocked: no documented consent')}${kpi('New emails sent today', n(c.newToday), `Limit ${s.max_new_per_day} · ${esc(s.new_email_time)}`)}
        ${kpi('Reminders sent today', n(c.remindersToday), `Limit ${s.max_reminders_per_day} · ${esc(s.reminder_time)}`)}${kpi('Delivered', n(c.delivered))}${kpi('Failed', n(c.failed))}${kpi('Bounced', n(c.bounced), `${n(c.hardBounced)} hard-bounced addresses suppressed`)}
        ${kpi('Unsubscribed', n(c.unsubscribed), `${n(c.complaints)} spam complaints`)}${kpi('Registrations from campaigns', n(c.registrations))}${kpi('Successful ₹49 payments', n(c.paid))}${kpi('Verified advocate profiles', n(c.verified))}
      </div>
      <div class="grid" style="grid-template-columns:2fr 1fr;margin-top:14px;gap:14px">
        <div class="card"><div class="row between"><div><div class="strong">Daily activity</div><div class="muted small">Last 14 days</div></div>${legend([[COL.a, 'New emails'], [COL.b, 'Reminders']])}</div><div class="chart">${barChart(o.series, ['new', 'reminders'], [COL.a, COL.b])}</div></div>
        <div class="card"><div class="strong">Next scheduled runs</div><div class="small" style="margin-top:8px;line-height:2">New emails: <b>${dt(o.next.new)}</b><br>Reminders: <b>${dt(o.next.reminder)}</b><br>Daily report: <b>${dt(o.next.report)}</b></div><div class="muted small" style="margin-top:8px">${s.dry_run ? 'DRY RUN: the schedule simulates and sends nothing.' : ''}</div></div>
      </div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Campaign performance</div>${campaignTable(o.campaigns)}</div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Recent scheduled jobs</div>${tbl([['Job'], ['Started'], ['Finished'], ['Result']], o.jobs.map(j => `<tr><td class="mono">${esc(j.job_key)}</td><td>${dt(j.started_at)}</td><td>${dt(j.finished_at)}</td><td class="small muted">${esc(summ(j.summary))}</td></tr>`), 'No job has run yet.')}</div>`;
    m.querySelector('#kill').onclick = async e => { if (!s.kill_switch && !confirm('Halt all email sending immediately?')) return; await busy(e.target, 'Working…', async () => { await api('kill', { on: !s.kill_switch }); toast(s.kill_switch ? 'Emergency stop released' : 'All sending halted'); SCREENS.overview(m); }); };
  };
  const summ = o => !o ? '' : Object.entries(o).filter(([k, v]) => typeof v !== 'object').map(([k, v]) => `${k}: ${v}`).join(' · ');
  const campaignTable = rows => tbl([['Campaign'], ['Sent', 'num'], ['Delivered', 'num'], ['Clicked', 'num'], ['Bounced', 'num'], ['Unsubscribed', 'num'], ['Registered', 'num'], ['Paid', 'num']], rows.map(r => `<tr><td class="strong">${esc(r.name)}</td><td class="num">${n(r.sent)}</td><td class="num">${n(r.delivered)}</td><td class="num">${n(r.clicked)}</td><td class="num">${n(r.bounced)}</td><td class="num">${n(r.unsubscribed)}</td><td class="num">${n(r.registered)}</td><td class="num">${n(r.paid)}</td></tr>`));

  // ---------- 2. contacts ----------
  SCREENS.contacts = async (m, cid) => {
    if (cid) return contactPage(m, cid);
    const st = cs.contacts = cs.contacts || { page: 0, filters: {} };
    const r = await api('contacts', { page: st.page, size: 25, filters: st.filters }), f = st.filters;
    const sel = (k, label, opts) => `<label class="f">${label}<select data-f="${k}"><option value="">All</option>${opts.map(o => `<option ${f[k] === (o[0] ?? o) ? 'selected' : ''} value="${esc(o[0] ?? o)}">${esc(o[1] ?? o)}</option>`).join('')}</select></label>`;
    m.innerHTML = `<div class="row between"><div><h1>Contact Database</h1><p class="sub">${n(r.total)} contacts match</p></div><div class="row"><button class="btn" data-x="csv">Export CSV</button><button class="btn" data-x="xls">Export Excel</button></div></div>
      <div class="card" style="margin-bottom:14px"><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))"><label class="f">Search<input data-f="q" value="${esc(f.q || '')}" placeholder="Name, email or ID"></label>
        ${sel('state', 'State', r.states)}${sel('city', 'City', r.cities)}${sel('consent', 'Consent status', [['UNKNOWN', 'Unknown'], ['GRANTED', 'Granted'], ['WITHDRAWN', 'Withdrawn']])}${sel('email_status', 'Email status', [['BLOCKED', 'Blocked'], ['ELIGIBLE', 'Eligible'], ['QUEUED', 'Queued'], ['SENT', 'Sent'], ['FAILED', 'Failed']])}
        ${sel('registration', 'Registration', [['NONE', 'None'], ['STARTED', 'Started'], ['COMPLETED', 'Registered']])}${sel('payment', 'Payment', [['NONE', 'None'], ['PAID', 'Paid']])}</div></div>
      <div class="card">${tbl([['Advocate'], ['Email'], ['City'], ['State'], ['Source'], ['Consent'], ['First email'], ['First sent'], ['Reminders'], ['Registration'], ['Payment']], r.rows.map(c => `<tr style="cursor:pointer" data-c="${esc(c.contact_id)}"><td class="strong">${esc(c.advocate_name || '—')}<div class="muted small mono">${esc(c.contact_id)}</div></td><td>${esc(c.email)}</td><td>${esc(c.city)}</td><td>${esc(c.state)}</td><td class="small">${esc(c.contact_source)}</td><td>${chipOf(c.consent_status, CONSENT)}</td><td>${chipOf(c.first_email_status, FIRST)}</td><td class="small">${day(c.first_email_date)}</td><td class="small">${esc(reminderText(c))}</td><td>${chipOf(c.registration_status, REG)}</td><td>${chipOf(c.payment_status, PAY)}</td></tr>`), 'No contacts match. Import the sheet from Google Sheets Integration.')}${pager(r.page, r.total, r.size)}</div>`;
    m.querySelectorAll('[data-f]').forEach(i => i.onchange = () => { st.filters[i.dataset.f] = i.value; st.page = 0; SCREENS.contacts(m); });
    m.querySelector('[data-f="q"]').onkeydown = e => { if (e.key === 'Enter') e.target.onchange(); };
    m.querySelectorAll('[data-pg]').forEach(b => b.onclick = () => { st.page += Number(b.dataset.pg); SCREENS.contacts(m); });
    m.querySelectorAll('[data-c]').forEach(tr => tr.onclick = () => { location.hash = 'email/contacts:' + tr.dataset.c; });
    m.querySelectorAll('[data-x]').forEach(b => b.onclick = e => busy(b, 'Preparing…', async () => { const x = await api('export', { filters: st.filters, format: b.dataset.x }); download(x.filename, x.mime, x.content); toast('Export ready'); }));
  };
  async function contactPage(m, cid) {
    const d = await api('contact', { contact_id: cid }), c = d.contact;
    m.innerHTML = `<a href="#email/contacts" class="small">← All contacts</a><div class="row between" style="margin-top:6px"><div><h1>${esc(c.advocate_name || c.email)}</h1><p class="sub mono">${esc(c.contact_id)} · ${esc(c.email)}</p></div><div class="row">${chipOf(c.consent_status, CONSENT)}${chipOf(c.first_email_status, FIRST)}${c.unsubscribe_status === 'UNSUBSCRIBED' ? '<span class="chip c-bad">Unsubscribed</span>' : ''}${c.hard_bounced ? '<span class="chip c-bad">Hard bounce</span>' : ''}${c.spam_complaint ? '<span class="chip c-bad">Spam complaint</span>' : ''}</div></div>
      <div class="grid k3"><div class="card small" style="line-height:1.9"><b>Profile</b><br>City: ${esc(c.city) || '—'}<br>State: ${esc(c.state) || '—'}<br>Source: ${esc(c.contact_source) || '—'} ${c.source_url ? `<a href="${esc(c.source_url)}" target="_blank" rel="noopener noreferrer">link</a>` : ''}<br>Imported: ${dt(c.created_at)}</div>
        <div class="card small" style="line-height:1.9"><b>Campaign state</b><br>First email: ${esc(c.first_email_status)} ${c.first_email_date ? '· ' + dt(c.first_email_date) : ''}<br>Reminders: ${esc(reminderText(c))}<br>Registration: ${chipOf(c.registration_status, REG)} · Payment: ${chipOf(c.payment_status, PAY)}<br>Profile verified: ${c.profile_verified ? 'Yes' : 'No'}</div>
        <div class="card small" style="line-height:1.9"><b>Marketing consent</b><br>Status: ${esc(c.consent_status)}<br>Source: ${esc(c.consent_source) || '—'}<br>Given: ${dt(c.consent_timestamp)}<br>Email verified: ${dt(c.consent_verified_at)}<div class="row" style="margin-top:8px"><button class="btn sm pri" id="addc">Record consent</button>${c.consent_status === 'GRANTED' && !c.consent_verified_at ? '<button class="btn sm" id="ver">Mark email verified</button>' : ''}</div></div></div>
      ${d.suppression ? `<div class="banner bad" style="margin-top:14px">On the suppression list: <b>${esc(d.suppression.reason.replace('_', ' '))}</b> since ${dt(d.suppression.created_at)} (${esc(d.suppression.source)}). No marketing email will be sent.</div>` : ''}
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Consent audit trail</div>${tbl([['Consent ID'], ['Purpose'], ['Source'], ['Wording'], ['Given'], ['Verified'], ['Withdrawn'], ['Evidence']], d.consents.map(x => `<tr><td class="mono small">${esc(String(x.consent_id).slice(0, 8))}</td><td>${esc(x.purpose)}</td><td>${esc(x.consent_source)}</td><td>${esc(x.wording_version) || '—'}</td><td>${dt(x.consented_at)}</td><td>${dt(x.verified_at)}</td><td>${dt(x.withdrawn_at)}</td><td class="small">${esc(x.evidence_ref)}</td></tr>`), 'No consent has been recorded. This contact is blocked from marketing email.')}<div class="muted small" style="margin-top:8px">Essential transactional emails (receipts, account and security notices) are a separate permission and are never sent from this module.</div></div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Email history</div>${tbl([['When'], ['Subject'], ['Status'], ['Detail']], d.logs.map(l => `<tr><td>${dt(l.created_at)}</td><td>${esc(l.subject)}</td><td>${chipOf(l.status, QSTAT)}</td><td class="small muted">${esc(l.error || l.provider_message_id || '')}</td></tr>`), 'No emails have been sent to this contact.')}</div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Events</div>${tbl([['When'], ['Event'], ['Detail']], d.events.map(e => `<tr><td>${dt(e.occurred_at)}</td><td class="mono">${esc(e.event_type)}</td><td class="small muted">${esc(Object.values(e.meta || {}).join(' '))}</td></tr>`), 'No events yet.')}</div>`;
    const reload = () => SCREENS.contacts(m, cid);
    m.querySelector('#addc').onclick = () => modal(`<h2>Record marketing consent</h2><p class="muted small" style="margin:0">Only record permission the person actually gave for this purpose. Public listings are not consent. Keep the evidence (form record, email, ticket) and reference it here.</p>
      <label class="f">Where was permission given?<input id="s" placeholder="e.g. Legal Staff sign-up form"></label><div class="two"><label class="f">Date given<input id="a" type="date"></label><label class="f">Email verified on (optional)<input id="v" type="date"></label></div>
      <label class="f">Consent wording version<input id="w" placeholder="e.g. v1"></label><label class="f">Evidence reference (required)<input id="e" placeholder="Form entry ID, ticket or file"></label><div class="err" id="er"></div><div class="row" style="justify-content:flex-end"><button class="btn" id="x">Cancel</button><button class="btn pri" id="go">Save consent</button></div>`, (mm, close) => {
      mm.querySelector('#x').onclick = close; mm.querySelector('#go').onclick = async e => { try { await api('consent_record', { contact_id: cid, source: mm.querySelector('#s').value, consented_at: mm.querySelector('#a').value, verified_at: mm.querySelector('#v').value || null, wording_version: mm.querySelector('#w').value, evidence_ref: mm.querySelector('#e').value }); close(); toast('Consent recorded'); reload(); } catch (er) { mm.querySelector('#er').textContent = er.message; } }; });
    const v = m.querySelector('#ver'); if (v) v.onclick = () => busy(v, 'Saving…', async () => { await api('consent_verify', { contact_id: cid }); toast('Email marked verified'); reload(); });
  }

  // ---------- 3. Google Sheets ----------
  SCREENS.sheets = async m => {
    const g = await api('sheets_get'), imp = (await api('imports')).rows; let i = g.integration, headers = [], sheets = [];
    if (i && g.google_connected) { try { const r = await api('sheets_connect', { url: i.spreadsheet_url || i.spreadsheet_id, sheet: i.sheet_name }); headers = r.headers; sheets = r.sheets; i = r.integration; } catch (e) { toast(e.message); } }
    const LABEL = { advocate_name: 'Advocate name', email: 'Email (required)', city: 'City', state: 'State', contact_source: 'Contact source', source_url: 'Source URL', consent_source: 'Consent source', consent_timestamp: 'Consent date', consent_verified_at: 'Consent verified date', consent_evidence_ref: 'Consent evidence reference', consent_wording_version: 'Consent wording version' };
    m.innerHTML = `<h1>Google Sheets Integration</h1><p class="sub">The sheet stays the source. Imported contacts start as consent UNKNOWN and are blocked from marketing.</p>
      ${g.google_connected ? `<div class="banner ok">Google is connected through a read-only service account. Share your spreadsheet (Viewer) with <b class="mono">${esc(g.service_account)}</b>.</div>` : `<div class="banner warn"><b>Google is not connected.</b> Add the <span class="mono">GOOGLE_SERVICE_ACCOUNT_JSON</span> function secret (see the deployment guide), then share the sheet with the service account.</div>`}
      <div class="card"><div class="strong" style="margin-bottom:10px">Connect a sheet</div><div class="row"><input id="url" style="flex:1;min-width:260px" placeholder="Spreadsheet URL or ID" value="${esc(i ? i.spreadsheet_url || i.spreadsheet_id : '')}"><button class="btn pri" id="conn" ${g.google_connected ? '' : 'disabled'}>Connect Google Sheet</button></div></div>
      ${i ? `<div class="card" style="margin-top:14px"><div class="row between"><div><div class="strong">${esc(i.spreadsheet_title)}</div><div class="muted small">Last sync: ${dt(i.last_sync_at)} · ${esc(i.last_sync_status)}</div></div><div class="row"><label class="switch small"><input type="checkbox" id="auto" ${i.sync_enabled ? 'checked' : ''}> Sync automatically</label><button class="btn sm" id="prev">Preview import</button><button class="btn sm pri" id="sync">Sync now</button></div></div>
        <div class="two" style="margin-top:14px"><label class="f">Sheet<select id="sheet">${sheets.map(s => `<option ${s.title === i.sheet_name ? 'selected' : ''}>${esc(s.title)}</option>`).join('')}</select></label></div>
        <div class="strong" style="margin:14px 0 8px">Column mapping</div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(210px,1fr))">${g.mappable.map(f => `<label class="f">${LABEL[f]}<select data-m="${f}"><option value="">— not in the sheet —</option>${headers.map(h => `<option ${(i.column_map || {})[f] === h ? 'selected' : ''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>
        <div class="muted small" style="margin-top:8px">Consent columns are optional and are only honoured when a source, a date and an evidence reference are all present and the source is not a public listing.</div><div class="row" style="margin-top:12px"><button class="btn" id="save">Save mapping</button></div><div id="pv" style="margin-top:14px"></div></div>` : ''}
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Import history</div>${tbl([['Started'], ['Trigger'], ['Status'], ['Rows', 'num'], ['New', 'num'], ['Updated', 'num'], ['Duplicates', 'num'], ['Invalid', 'num'], ['Consents', 'num'], ['Errors']], imp.map(r => `<tr><td>${dt(r.started_at)}</td><td>${esc(r.trigger)}</td><td>${chipOf(r.status === 'completed' ? 'sent' : r.status === 'failed' ? 'failed' : 'queued', QSTAT)}</td><td class="num">${n(r.rows_read)}</td><td class="num">${n(r.rows_new)}</td><td class="num">${n(r.rows_updated)}</td><td class="num">${n(r.rows_duplicate)}</td><td class="num">${n(r.rows_invalid)}</td><td class="num">${n(r.consents_recognised)}</td><td class="small muted">${esc((r.errors || []).slice(0, 2).map(e => (e.row ? 'Row ' + e.row + ': ' : '') + e.error).join(' · '))}</td></tr>`), 'No import has run yet.')}</div>`;
    m.querySelector('#conn').onclick = e => busy(e.target, 'Connecting…', async () => { await api('sheets_connect', { url: m.querySelector('#url').value }); toast('Sheet connected'); SCREENS.sheets(m); });
    if (!i) return;
    const map = () => { const o = {}; m.querySelectorAll('[data-m]').forEach(s => { if (s.value) o[s.dataset.m] = s.value; }); return o; };
    m.querySelector('#sheet').onchange = e => busy(e.target, '…', async () => { await api('sheets_connect', { url: i.spreadsheet_url || i.spreadsheet_id, sheet: e.target.value }); SCREENS.sheets(m); });
    m.querySelector('#save').onclick = e => busy(e.target, 'Saving…', async () => { await api('sheets_save', { id: i.id, column_map: map(), sheet: m.querySelector('#sheet').value }); toast('Mapping saved'); });
    m.querySelector('#auto').onchange = async e => { try { await api('sheets_save', { id: i.id, sync_enabled: e.target.checked }); toast(e.target.checked ? 'Automatic sync on' : 'Automatic sync off'); } catch (er) { toast(er.message); e.target.checked = !e.target.checked; } };
    m.querySelector('#prev').onclick = e => busy(e.target, 'Reading…', async () => { const r = await api('sheets_preview', { id: i.id, column_map: map(), sheet: m.querySelector('#sheet').value }); m.querySelector('#pv').innerHTML = `<div class="grid k6" style="margin-bottom:10px">${kpi('Rows', n(r.total))}${kpi('New', n(r.new))}${kpi('Already known', n(r.existing))}${kpi('Duplicates in sheet', n(r.duplicates))}${kpi('Invalid emails', n(r.invalid))}${kpi('Valid', n(r.valid))}</div><div class="muted small" style="margin-bottom:8px">${esc(r.note)}</div>${tbl([['Row'], ['Name'], ['Email'], ['City'], ['State'], ['Source']], r.sample.map(x => `<tr><td>${x.row}</td><td>${esc(x.advocate_name)}</td><td>${esc(x.email)}</td><td>${esc(x.city)}</td><td>${esc(x.state)}</td><td>${esc(x.contact_source)}</td></tr>`))}`; });
    m.querySelector('#sync').onclick = e => busy(e.target, 'Importing…', async () => { await api('sheets_save', { id: i.id, column_map: map(), sheet: m.querySelector('#sheet').value }); const r = await api('sheets_sync', { id: i.id }); toast(`Imported: ${n(r.new)} new, ${n(r.updated)} updated, ${n(r.duplicate)} duplicates, ${n(r.invalid)} invalid`); SCREENS.sheets(m); });
  };

  // ---------- 4 + 5. campaigns ----------
  const campaignScreen = kind => async m => {
    const [cp, q, sim] = await Promise.all([api('campaigns'), api('queue'), api('simulate', { kind, quiet: true })]), list = cp.campaigns.filter(c => c.kind === kind), p = sim[kind];
    m.innerHTML = `<h1>${kind === 'new' ? 'New Email Campaigns' : 'Reminder Campaigns'}</h1><p class="sub">${kind === 'new' ? 'First-time emails to contacts with documented, verified marketing permission.' : 'Follow-ups after the configured number of days; at most two in total; stopped by registration, payment, unsubscribe or bounce.'}</p>
      <div class="grid k3">${kpi('Daily limit', n(p.cap), `${n(p.remaining)} left today`)}${kpi('Would be selected next run', n(p.selected.length), 'Dry-run simulation, nothing is sent')}${kpi('Rejected in simulation', n(p.skipped.length), 'Safety checks')}</div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Campaigns</div>${campaignTable(list)}<div class="muted small" style="margin-top:8px">Templates are edited under Email Templates. Every send re-checks consent, suppression, bounce, conversion and approval flags.</div></div>
      <div class="card" style="margin-top:14px"><div class="row between"><div class="strong">Next run simulation</div><button class="btn sm" id="re">Run again</button></div>${tbl([['Contact'], ['Email'], ['Campaign']], p.selected.slice(0, 50).map(s => `<tr><td>${esc(s.name)} <span class="muted small mono">${esc(s.contact_id)}</span></td><td>${esc(s.email)}</td><td class="mono">${esc(s.campaign)}</td></tr>`), 'Nobody is eligible. Contacts need documented marketing consent, a verified email, and must not be suppressed or converted.')}${p.skipped.length ? `<details style="margin-top:10px"><summary class="small muted" style="cursor:pointer">Why ${n(p.skipped.length)} candidates were rejected</summary>${tbl([['Contact'], ['Reasons']], p.skipped.slice(0, 50).map(s => `<tr><td class="mono small">${esc(s.contact_id)}</td><td class="small">${esc(s.reasons.join('; '))}</td></tr>`))}</details>` : ''}</div>`;
    m.querySelector('#re').onclick = () => campaignScreen(kind)(m);
  };
  SCREENS.new = campaignScreen('new'); SCREENS.reminders = campaignScreen('reminder');

  // ---------- 6. templates ----------
  SCREENS.templates = async (m, key) => {
    const r = await api('templates'), settings = (await api('settings')).settings, t = r.rows.find(x => x.key === key) || r.rows[0];
    m.innerHTML = `<h1>Email Templates</h1><p class="sub">${settings.legal_approval ? 'Legal approval is recorded: templates can be activated.' : '<b>Templates can only be activated after legal approval is recorded in Automation Settings.</b>'}</p>
      <div class="split"><div class="card" style="padding:0">${r.rows.map(x => `<div class="tpl-item ${x.key === t.key ? 'on' : ''}" data-k="${x.key}"><div class="row between"><b>${esc(x.name)}</b><span class="chip ${x.active ? 'c-good' : 'c-mut'}">${x.active ? 'Active' : 'Inactive'}</span></div><div class="muted small">${esc(x.subject)}</div></div>`).join('')}</div>
      <div class="card grid" style="gap:12px"><div class="row between"><div class="strong">${esc(t.name)} <span class="muted small">v${t.version}</span></div><label class="switch small"><input type="checkbox" id="act" ${t.active ? 'checked' : ''}> Active</label></div>
        <label class="f">Name<input id="nm" value="${esc(t.name)}"></label><label class="f">Subject<input id="sj" value="${esc(t.subject)}"></label>
        <label class="f">Body (HTML)<span class="vars">Variables you can use: ${r.vars.map(v => `<code>{{${v}}}</code>`).join(' ')}</span><textarea id="bh" rows="14" class="mono">${esc(t.body_html)}</textarea></label>
        <label class="f">Plain-text version (optional; made from the HTML when empty)<textarea id="bt" rows="5" class="mono">${esc(t.body_text)}</textarea></label><div class="err" id="er"></div>
        <div class="row"><button class="btn pri" id="sv">Save template</button><button class="btn" id="pv">Preview</button><button class="btn" id="ts">Send test to me</button></div>
        <div class="row between"><div class="strong small">Preview</div><div class="seg" id="seg"><button class="on" data-w="640">Desktop</button><button data-w="375">Mobile</button></div></div><div style="display:flex;justify-content:center;background:#F5F5F4;border-radius:10px;padding:10px;overflow-x:auto;max-width:100%"><iframe class="frame" id="fr" sandbox="" style="flex:none;width:640px" title="Email preview"></iframe></div><div class="muted small" id="psub"></div></div></div>`;
    m.querySelectorAll('[data-k]').forEach(x => x.onclick = () => { location.hash = 'email/templates:' + x.dataset.k; });
    const body = () => ({ key: t.key, name: m.querySelector('#nm').value, subject: m.querySelector('#sj').value, body_html: m.querySelector('#bh').value, body_text: m.querySelector('#bt').value });
    const preview = async () => { try { const r2 = await api('template_preview', body()); m.querySelector('#fr').srcdoc = r2.html; m.querySelector('#psub').textContent = 'Subject: ' + r2.subject; m.querySelector('#er').textContent = ''; } catch (e) { m.querySelector('#er').textContent = e.message; } };
    preview(); m.querySelector('#pv').onclick = preview;
    m.querySelectorAll('#seg button').forEach(b => b.onclick = () => { m.querySelectorAll('#seg button').forEach(x => x.classList.toggle('on', x === b)); m.querySelector('#fr').style.width = b.dataset.w + 'px'; });
    m.querySelector('#sv').onclick = e => busy(e.target, 'Saving…', async () => { try { await api('template_save', body()); toast('Template saved'); SCREENS.templates(m, t.key); } catch (er) { m.querySelector('#er').textContent = er.message; } });
    m.querySelector('#ts').onclick = e => busy(e.target, 'Sending…', async () => { try { const x = await api('template_test', body()); toast('Test sent to ' + x.sent_to); } catch (er) { m.querySelector('#er').textContent = er.message; } });
    m.querySelector('#act').onchange = async e => { try { await api('template_toggle', { key: t.key, active: e.target.checked }); toast(e.target.checked ? 'Template activated' : 'Template deactivated'); SCREENS.templates(m, t.key); } catch (er) { toast(er.message); e.target.checked = !e.target.checked; } };
  };

  // ---------- 7. queue ----------
  SCREENS.queue = async m => {
    const r = await api('queue'); const cnt = r.counts || {};
    m.innerHTML = `<div class="row between"><div><h1>Sending Queue</h1><p class="sub">Emails waiting to go out, and recent failures and skips. Each one is checked again just before it is sent.</p></div><button class="btn danger" id="cx" ${r.rows.some(x => x.status === 'queued') ? '' : 'disabled'}>Cancel all queued</button></div>
      <div class="grid k4">${['queued', 'sent', 'skipped', 'failed'].map(s => kpi(s[0].toUpperCase() + s.slice(1), n(cnt[s] || 0), 'last 7 days')).join('')}</div>
      <div class="card" style="margin-top:14px">${tbl([['Created'], ['Contact'], ['Campaign'], ['Status'], ['Attempts', 'num'], ['Detail']], r.rows.map(x => `<tr><td>${dt(x.created_at)}</td><td>${esc(x.email_contacts?.advocate_name || '')} <span class="muted small">${esc(x.email_contacts?.email_normalized || '')}</span></td><td class="mono">${esc(x.email_campaigns?.code || '')}</td><td>${chipOf(x.status, QSTAT)}</td><td class="num">${x.attempts}</td><td class="small muted">${esc(x.skip_reason || x.last_error || '')}</td></tr>`), 'The queue is empty.')}</div>`;
    m.querySelector('#cx').onclick = e => { if (!confirm('Cancel every queued email? Contacts go back to eligible.')) return; busy(e.target, 'Cancelling…', async () => { const x = await api('queue_cancel'); toast(`${x.cancelled} cancelled`); SCREENS.queue(m); }); };
  };

  // ---------- 8. history ----------
  SCREENS.history = async m => {
    const st = cs.history = cs.history || { page: 0, status: '', q: '' }, r = await api('history', st);
    m.innerHTML = `<h1>Email History</h1><p class="sub">${n(r.total)} entries. Dry runs never appear here: they send nothing.</p><div class="card"><div class="row" style="margin-bottom:12px"><input id="q" style="max-width:260px" placeholder="Search address" value="${esc(st.q)}"><select id="s" style="max-width:170px"><option value="">All statuses</option>${['accepted', 'failed', 'skipped'].map(s => `<option ${st.status === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div>
      ${tbl([['When'], ['To'], ['Campaign'], ['Subject'], ['Status'], ['Provider ID / error']], r.rows.map(l => `<tr><td>${dt(l.created_at)}</td><td>${esc(l.to_email)}</td><td class="mono">${esc(l.email_campaigns?.code || '')}</td><td>${esc(l.subject)}</td><td>${chipOf(l.status, QSTAT)}</td><td class="small muted mono">${esc(l.error || l.provider_message_id || '')}</td></tr>`), 'No emails have been sent yet.')}${pager(r.page, r.total, 50)}</div>`;
    m.querySelector('#q').onkeydown = e => { if (e.key === 'Enter') { st.q = e.target.value; st.page = 0; SCREENS.history(m); } }; m.querySelector('#s').onchange = e => { st.status = e.target.value; st.page = 0; SCREENS.history(m); };
    m.querySelectorAll('[data-pg]').forEach(b => b.onclick = () => { st.page += Number(b.dataset.pg); SCREENS.history(m); });
  };

  // ---------- 9. unsubscribed ----------
  SCREENS.unsub = async m => {
    const st = cs.unsub = cs.unsub || { page: 0 }, r = await api('suppressions', st), R = { unsubscribed: ['Unsubscribed', 'c-warn'], hard_bounce: ['Hard bounce', 'c-bad'], spam_complaint: ['Spam complaint', 'c-bad'], invalid: ['Invalid', 'c-bad'], manual: ['Manual', 'c-mut'] };
    m.innerHTML = `<h1>Unsubscribed Contacts</h1><p class="sub">The suppression list: ${n(r.total)} addresses that never receive marketing email. Bounces and complaints cannot be lifted.</p>
      <div class="card" style="margin-bottom:14px"><div class="row"><input id="em" style="max-width:300px" type="email" placeholder="Add an address to the list"><button class="btn" id="add">Suppress</button></div></div>
      <div class="card">${tbl([['Address'], ['Reason'], ['Source'], ['Since'], ['']], r.rows.map(x => `<tr><td>${esc(x.email_normalized)}</td><td>${chipOf(x.reason, R)}</td><td class="small">${esc(x.source)}</td><td>${dt(x.created_at)}</td><td class="num">${x.reason === 'unsubscribed' ? `<button class="btn sm" data-l="${esc(x.email_normalized)}">Lift with fresh permission</button>` : ''}</td></tr>`), 'Nobody has unsubscribed.')}${pager(r.page, r.total, 50)}</div>`;
    m.querySelector('#add').onclick = e => busy(e.target, 'Saving…', async () => { await api('suppress_add', { email: m.querySelector('#em').value }); toast('Added to the suppression list'); SCREENS.unsub(m); });
    m.querySelectorAll('[data-pg]').forEach(b => b.onclick = () => { st.page += Number(b.dataset.pg); SCREENS.unsub(m); });
    m.querySelectorAll('[data-l]').forEach(b => b.onclick = () => modal(`<h2>Lift unsubscribe</h2><p class="muted small" style="margin:0">Only do this when the person has given fresh permission. The contact returns to consent UNKNOWN and stays blocked until a new consent is recorded.</p><label class="f">Where is the fresh permission documented?<input id="n" placeholder="Reference"></label><div class="err" id="er"></div><div class="row" style="justify-content:flex-end"><button class="btn" id="x">Cancel</button><button class="btn pri" id="go">Lift</button></div>`, (mm, close) => {
      mm.querySelector('#x').onclick = close; mm.querySelector('#go').onclick = async () => { try { await api('suppression_lift', { email: b.dataset.l, note: mm.querySelector('#n').value }); close(); toast('Unsubscribe lifted'); SCREENS.unsub(m); } catch (er) { mm.querySelector('#er').textContent = er.message; } }; }));
  };

  // ---------- 10. analytics ----------
  SCREENS.analytics = async m => {
    const days = cs.days || 30, a = await api('analytics', { days }), tot = k => a.series.reduce((s, d) => s + (d[k] || 0), 0);
    m.innerHTML = `<div class="row between"><div><h1>Campaign Analytics</h1><p class="sub">Opens are not shown: they are not a confirmed human interaction. Clicks, registrations and payments are.</p></div><div class="seg" id="rg">${[14, 30, 90].map(d => `<button data-d="${d}" class="${d === days ? 'on' : ''}">${d} days</button>`).join('')}</div></div>
      <div class="grid k6">${kpi('Sent', n(tot('new') + tot('reminders')))}${kpi('Delivered', n(tot('delivered')))}${kpi('Clicked', n(tot('clicked')))}${kpi('Registered', n(tot('registered')))}${kpi('Paid ₹49', n(tot('paid')))}${kpi('Unsubscribed', n(tot('unsubscribed')))}</div>
      <div class="card" style="margin-top:14px"><div class="row between"><div class="strong">Emails sent per day</div>${legend([[COL.a, 'New'], [COL.b, 'Reminders']])}</div>${barChart(a.series, ['new', 'reminders'], [COL.a, COL.b])}</div>
      <div class="card" style="margin-top:14px"><div class="row between"><div class="strong">Responses per day</div>${legend([[COL.b, 'Delivered'], [COL.a, 'Clicked'], [COL.d, 'Registered'], [COL.c, 'Bounced']])}</div>${barChart(a.series, ['delivered', 'clicked', 'registered', 'bounced'], [COL.b, COL.a, COL.d, COL.c])}</div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">By campaign (all time)</div>${campaignTable(a.campaigns)}</div>`;
    m.querySelectorAll('#rg button').forEach(b => b.onclick = () => { cs.days = Number(b.dataset.d); SCREENS.analytics(m); });
  };

  // ---------- 11. settings ----------
  SCREENS.settings = async m => {
    const [r, au] = await Promise.all([api('settings'), api('audit')]), s = r.settings, p = r.provider, MJ = p.name === 'mailjet', PN = MJ ? 'Mailjet' : 'Brevo';
    const ck = (k, l) => `<label class="switch"><input type="checkbox" data-k="${k}" ${s[k] ? 'checked' : ''}> ${l}</label>`, inp = (k, l, t = 'text', extra = '') => `<label class="f">${l}<input data-k="${k}" type="${t}" value="${esc(s[k] ?? '')}" ${extra}></label>`;
    m.innerHTML = `<h1>Automation Settings</h1><p class="sub">Live sending needs both approvals below, dry run turned off and a verified sender domain. Every change is recorded in the audit log.</p>
      <div class="banner ${r.blockers.length ? 'warn' : 'ok'}">${r.blockers.length ? `<b>Sending is disabled.</b><ul>${r.blockers.map(b => `<li>${esc(b)}</li>`).join('')}</ul>` : '<b>All conditions for production sending are met.</b>'}</div>
      <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(340px,1fr))">
        <div class="card grid" style="gap:12px;align-content:start"><div class="strong">Approvals and switches</div>${ck('legal_approval', 'Legal approval: the directory campaign has been legally approved')}${inp('legal_approval_ref', 'Where the legal approval is documented')}${ck('provider_approved', 'Provider approval: the email provider has approved this use')}${inp('provider_approval_ref', 'Where the provider approval is documented')}
          ${ck('system_enabled', 'Automation: send emails automatically on schedule')}${ck('dry_run', 'Dry run: only simulate, send nothing')}${ck('allow_public_record', 'Email contacts listed in an official government record (not an opt-in; unsubscribe still applies)')}${inp('public_record_ref', 'Where this basis is documented (needs legal approval)')}<button class="btn" id="pr" type="button">Mark contacts from the official listing…</button><div class="muted small">Withdrawing an approval switches automation off and deactivates the templates.</div></div>
        <div class="card grid" style="gap:12px;align-content:start"><div class="strong">Limits and timing (India time)</div><div class="two">${inp('max_new_per_day', 'New emails per day (max)', 'number', 'min="0"')}${inp('max_reminders_per_day', 'Reminders per day (max)', 'number', 'min="0"')}</div><div class="two">${inp('new_email_time', 'New emails sent at', 'time')}${inp('reminder_time', 'Reminders sent at', 'time')}</div><div class="two">${inp('report_time', 'Daily report sent at', 'time')}${inp('report_to', 'Daily report goes to', 'email')}</div><div class="two">${inp('reminder_after_days', 'Days before a reminder', 'number', 'min="1"')}${inp('max_reminders', 'Follow-ups per contact (max)', 'number', 'min="0"')}</div>${inp('sheet_sync_hours', 'Sheet sync every (hours)', 'number', 'min="1"')}
          <div class="small muted" style="line-height:1.9">Next: new emails <b>${dt(r.next.new)}</b> · reminders <b>${dt(r.next.reminder)}</b> · report <b>${dt(r.next.report)}</b></div></div></div>
      <div class="err" id="er" style="margin-top:8px"></div><div class="row" style="margin-top:10px"><button class="btn pri" id="sv">Save settings</button><button class="btn" id="sim">Run dry-run simulation</button><button class="btn" id="pre">Preview scheduled messages</button><button class="btn" id="sy">Sync sheet now</button><button class="btn ${s.kill_switch ? '' : 'danger'}" id="kl">${s.kill_switch ? 'Release emergency stop' : 'Emergency stop'}</button></div><div id="out" style="margin-top:14px"></div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:10px">Email provider (${PN})</div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))">${[[MJ ? 'API key and secret key (MAILJET_API_KEY, MAILJET_SECRET_KEY)' : 'API key (server secret BREVO_API_KEY)', p.api_key_set], [MJ ? 'Webhook secret (MAILJET_WEBHOOK_SECRET)' : 'Webhook secret (BREVO_WEBHOOK_SECRET)', p.webhook_secret_set], ['Link-signing secret (EMAIL_TOKEN_SECRET)', p.token_secret_set], ['Google service account', p.google_sa_set], ['SPF', p.spf_ok], ['DKIM', p.dkim_ok], ['DMARC', p.dmarc_ok]].map(([l, v]) => `<div class="small">${l}: ${v == null ? '<span class="chip c-mut">Not checked</span>' : v ? '<span class="chip c-good">OK</span>' : '<span class="chip c-bad">Missing</span>'}</div>`).join('')}</div>
        <div class="muted small" style="margin:8px 0">Secrets live only in the function's server-side secrets and are never shown here. Webhook URL for ${PN}: ${MJ ? `<span class="mono">${esc(A.fnUrl('email-marketing'))}?action=webhook&amp;key=&lt;MAILJET_WEBHOOK_SECRET&gt;</span> (add it in Mailjet under Event tracking).` : `<span class="mono">${esc(A.fnUrl('email-marketing'))}?action=webhook</span> with header <span class="mono">Authorization: Bearer &lt;BREVO_WEBHOOK_SECRET&gt;</span>.`}</div>
        <div class="row"><input id="se" style="max-width:260px" type="email" placeholder="sender@yourdomain.in" value="${esc(p.sender_email)}"><input id="sn" style="max-width:200px" placeholder="Sender name" value="${esc(p.sender_name)}"><button class="btn" id="ps">Save sender</button><button class="btn" id="pc">Check SPF, DKIM, DMARC</button></div><div class="muted small" style="margin-top:6px">The DNS check is indicative; confirm authentication in the ${PN} dashboard. Personal mailboxes (Gmail etc.) are refused.</div></div>
      <div class="card" style="margin-top:14px"><div class="strong" style="margin-bottom:8px">Audit log</div>${tbl([['When'], ['Who'], ['Action'], ['Target'], ['Details']], au.rows.map(x => `<tr><td>${dt(x.created_at)}</td><td class="small">${esc(x.actor)}</td><td class="mono">${esc(x.action)}</td><td class="small">${esc(x.target)}</td><td class="small muted">${esc(JSON.stringify(x.details).slice(0, 140))}</td></tr>`), 'No actions recorded.')}</div>`;
    const read = () => { const o = {}; m.querySelectorAll('[data-k]').forEach(i => { o[i.dataset.k] = i.type === 'checkbox' ? i.checked : ['number'].includes(i.type) ? Number(i.value) : i.value; }); return o; };
    const er = m.querySelector('#er');
    m.querySelector('#sv').onclick = e => busy(e.target, 'Saving…', async () => { try { await api('settings_save', { settings: read() }); toast('Settings saved'); SCREENS.settings(m); } catch (x) { er.textContent = x.message; } });
    m.querySelector('#pr').onclick = () => modal(`<h2>Mark contacts from an official listing</h2><p class="muted small" style="margin:0">Every contact without a consent decision becomes PUBLIC_RECORD (not "consent granted") and eligible for the first email. Unsubscribed, bounced and suppressed addresses are skipped. Needs legal approval and the public-record switch saved first.</p><label class="f">Source name<input id="ps1" placeholder="e.g. State Bar Council advocate directory"></label><label class="f">Page address (https)<input id="ps2" placeholder="https://"></label><label class="f">Date you checked the page<input id="ps3" type="date"></label><label class="switch"><input type="checkbox" id="ps4"> These contacts come from that official page</label><div class="err" id="er2"></div><div class="row" style="justify-content:flex-end"><button class="btn" id="x">Cancel</button><button class="btn pri" id="go">Mark contacts</button></div>`, (mm, close) => {
      mm.querySelector('#x').onclick = close; mm.querySelector('#go').onclick = async () => { try { const x = await api('public_record_apply', { source: mm.querySelector('#ps1').value, source_url: mm.querySelector('#ps2').value, checked_at: mm.querySelector('#ps3').value, confirm: mm.querySelector('#ps4').checked }); close(); toast(`${n(x.marked)} contacts marked as public record`); } catch (e2) { mm.querySelector('#er2').textContent = e2.message; } }; });
    m.querySelector('#kl').onclick = e => { if (!s.kill_switch && !confirm('Halt all email sending immediately?')) return; busy(e.target, 'Working…', async () => { await api('kill', { on: !s.kill_switch }); toast(s.kill_switch ? 'Emergency stop released' : 'All sending halted'); SCREENS.settings(m); }); };
    m.querySelector('#sy').onclick = e => busy(e.target, 'Syncing…', async () => { const g = await api('sheets_get'); if (!g.integration) throw new Error('Connect a Google Sheet first.'); const x = await api('sheets_sync', { id: g.integration.id }); toast(`Imported: ${n(x.new)} new, ${n(x.updated)} updated`); });
    m.querySelector('#sim').onclick = e => busy(e.target, 'Simulating…', async () => { const x = await api('simulate'); m.querySelector('#out').innerHTML = `<div class="card"><div class="strong">Dry-run simulation (nothing sent, nothing queued)</div><div class="small" style="margin-top:6px">New emails: <b>${x.new.selected.length}</b> of cap ${x.new.cap} (${x.new.remaining} left today) · Reminders: <b>${x.reminder.selected.length}</b> of cap ${x.reminder.cap}</div><div class="muted small" style="margin-top:6px">${x.new.skipped.length + x.reminder.skipped.length} candidates were rejected by the safety checks.</div></div>`; });
    m.querySelector('#pre').onclick = e => busy(e.target, 'Rendering…', async () => { const x = await api('preview_schedule'); m.querySelector('#out').innerHTML = ['new', 'reminder'].map(k => `<div class="card" style="margin-bottom:12px"><div class="strong">${k === 'new' ? 'New emails' : 'Reminders'}: ${x[k].count} scheduled for the next run</div>${x[k].sample.length ? x[k].sample.map(s => `<div class="small" style="margin-top:10px"><b>To:</b> ${esc(s.to)} · <b>Subject:</b> ${esc(s.subject)}</div><iframe class="frame" sandbox="" style="height:300px;margin-top:6px" srcdoc="${esc(s.html)}"></iframe>`).join('') : '<div class="muted small">Nothing is eligible.</div>'}</div>`).join(''); });
    m.querySelector('#ps').onclick = e => busy(e.target, 'Saving…', async () => { await api('provider_save', { sender_email: m.querySelector('#se').value, sender_name: m.querySelector('#sn').value }); toast('Sender saved. Check the domain next.'); SCREENS.settings(m); });
    m.querySelector('#pc').onclick = e => busy(e.target, 'Checking DNS…', async () => { const x = await api('provider_check'); toast(x.all ? 'SPF, DKIM and DMARC all found' : 'Some records are missing'); SCREENS.settings(m); });
  };
});
